// === Tab: mySketch ===
let parameters = {
	"para0": 1.24,
	"para1": -1.25,
	"para2": -1.81,
	"para3": -1.91,
	"color": { h: 0, s: 1, v: 1 },
	"dark mode": true
}
let canvasSize = 750
let hitsDict = {}
let hits;
let x = 0;
let y = 0;

function setup() {
	createCanvas(canvasSize, canvasSize);
	colorMode(HSB, 100)
	const gui = new dat.GUI;
	for (let i = 0; i < 4; i++) {
		gui.add(parameters, "para" + i.toString()).min(-3).max(3).step(0.01).name("parameter" + (i + 1).toString()).onChange(redraw);
	}
  gui.addColor(parameters, 'color').onFinishChange(redraw);
	gui.add(parameters, "dark mode").onFinishChange(redraw);
	gui.add({onclick: () => {
		parameters["para"] = []
		for (let i = 0; i < 4; i++) {
			parameters["para" + i.toString()] = random(0, 1) + random([1, -2])
		}
		parameters["color"]["h"] = random(0, 360)
		// parameters["dark mode"] = random([true, false])
		redraw()
		for (let controller of gui.__controllers) {
			controller.updateDisplay();
		}
	}}, 'onclick').name('ROLL!');
}

function draw() {
	let paraString = ""
	for (let i = 0; i < 4; i++) {
		paraString += parameters["para" + i.toString()].toString() + ","
	}
	if (!(paraString in hitsDict)) hitsDict[paraString] = Array(canvasSize).fill(0).map(x => Array(canvasSize).fill(0));
	hits = hitsDict[paraString]
	if (parameters["dark mode"]) background(0);
	else background(255);
	image(getImage(), 0, 0);
}

// Get next position
function next(x, y) {
	let nx = (sin(parameters["para0"]*y) + parameters["para2"] * cos(parameters["para0"]*x))
	let ny = (sin(parameters["para1"]*x) + parameters["para3"] * cos(parameters["para1"]*y))
	return [nx, ny]
}

function getImage() {
	// Calculate hits
	let scale = 1
	for (let round = 0; round < 5*10**3; round++) {
		[x, y] = next(x, y)
		imgX = int(map(x, -4, 4, 0, canvasSize));
		imgY = int(map(y, -4, 4, 0, canvasSize));
		hits[imgX][imgY] += scale;
	}
	let maxHits = max(hits.map(x => max(x)))

	// Create image by hits
	let img = createImage(canvasSize, canvasSize);
	img.loadPixels();
	for (let m = 0; m < canvasSize; m++) {
		for (let n = 0; n < canvasSize; n++) {
			let num = hits[m][n];
			if (num == 0) continue;
			num = map(log(num), 0, log(maxHits), 0, 1);
			if (parameters["dark mode"]) img.set(m, n, color(map(parameters["color"]["h"], 0, 360, 0, 100), 100-num*90, 40+num*60));
			else img.set(m, n, color(map(parameters["color"]["h"], 0, 360, 0, 100), 10+num*90, 100-num*60));

		}
	}
	img.updatePixels();
	return img
}

